<script lang="ts">import {type Query,type Row,rows} from '../lib/api'; import{tr}from'../lib/i18n'; export let query:Query; export let models:Row[]=[]; export let logs=false; export let onchange:(q:Query)=>void; let timer:ReturnType<typeof setTimeout>; function update(key:string,value:any){query={...query,[key]:value,page:1};if(key==='period'&&value!=='custom'){query.start='';query.end='';}if(key==='mode'&&value==='model_call'&&query.tier==='mixed')query.tier='';onchange(query)} function search(value:string){clearTimeout(timer);timer=setTimeout(()=>update('search',value),250)}</script>
<div class="filters">{#if logs}<select aria-label={tr('显示模式')} value={query.mode} onchange={e=>update('mode',e.currentTarget.value)}><option value="user_request">{tr('用户请求')}</option><option value="model_call">{tr('模型调用')}</option></select>{/if}<select aria-label={tr('周期')} value={query.period} onchange={e=>update('period',e.currentTarget.value)}>{#each [['today','今天'],['yesterday','昨天'],['week','近 7 天'],['month','近 30 天'],['all','历史'],['custom','自定义']] as [v,l]}<option value={v}>{tr(l)}</option>{/each}</select>{#if query.period==='custom'}<input type="date" aria-label="Start date" value={query.start} onchange={e=>update('start',e.currentTarget.value)}/><span>–</span><input type="date" aria-label="End date" value={query.end} onchange={e=>update('end',e.currentTarget.value)}/>{/if}<input list="model-suggestions" aria-label={tr('模型')} placeholder={tr('全部模型')} value={query.model} onchange={e=>update('model',e.currentTarget.value)}/><datalist id="model-suggestions">{#each rows(models) as m}<option value={m.model}>{m.model}</option>{/each}</datalist><select aria-label={tr('速度')} value={query.tier} onchange={e=>update('tier',e.currentTarget.value)}><option value="">{tr('全部速度')}</option><option value="standard">Standard</option><option value="fast">Fast</option><option value="priority">Priority</option>{#if query.mode==='user_request'}<option value="mixed">Mixed</option>{/if}</select>{#if logs}<select aria-label={tr('状态')} value={query.status} onchange={e=>update('status',e.currentTarget.value)}><option value="">{tr('全部状态')}</option>{#each ['running','completed','aborted','unknown'] as v}<option value={v}>{v}</option>{/each}</select><input class="search" data-search aria-label={tr('搜索请求或聊天')} placeholder={tr('搜索请求或聊天')} value={query.search} oninput={e=>search(e.currentTarget.value)}/>{/if}</div>
